package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen0Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testDivide_NormalValue() {
        Complex c = new Complex(10.0, 5.0);
        Complex result = c.divide(2.0);
        assertEquals(5.0, result.getReal(), DELTA);
        assertEquals(2.5, result.getImaginary(), DELTA);
    }

    @Test
    public void testDivide_NegativeDivisor() {
        Complex c = new Complex(10.0, -5.0);
        Complex result = c.divide(-2.0);
        assertEquals(-5.0, result.getReal(), DELTA);
        assertEquals(2.5, result.getImaginary(), DELTA);
    }

    @Test
    public void testDivide_NaN_Receiver() {
        Complex c = Complex.NaN;
        Complex result = c.divide(1.0);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_NaN_Divisor() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(Double.NaN);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(0.0);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor_ZeroReceiver() {
        Complex c = Complex.ZERO;
        Complex result = c.divide(0.0);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor_FiniteReceiver() {
        Complex c = new Complex(1.0, 2.0);
        Complex result = c.divide(Double.POSITIVE_INFINITY);
        // !isInfinite() is true, should return ZERO
        assertEquals(0.0, result.getReal(), DELTA);
        assertEquals(0.0, result.getImaginary(), DELTA);
        assertFalse(result.isNaN());
        assertFalse(result.isInfinite());
    }

    @Test
    public void testDivide_InfiniteDivisor_InfiniteReceiver() {
        Complex c = Complex.INFINITY;
        Complex result = c.divide(Double.POSITIVE_INFINITY);
        // isInfinite() is true, should return NaN
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor_NegativeInfiniteReceiver() {
        // Complex.INFINITY is usually (inf, 0) or similar, but we test isInfinite() branch
        Complex c = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex result = c.divide(Double.NEGATIVE_INFINITY);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_PrecisionSmallValue() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(1e-300);
        // Real: 1 / 1e-300 = 1e300
        // Imaginary: 1 * 1e-300 = 1e-300
        assertEquals(1e300, result.getReal(), 1e290);
        assertEquals(1e-300, result.getImaginary(), 1e-310);
    }
}
